from boltons.cacheutils import LRU, LRI

def ll_view(c):
    "values as seen via linked list / link lookup"
    return {k: c._link_lookup[k][3] for k in c._link_lookup}  # VALUE index

def check(c, model, tag):
    # dict view
    d = dict(c)
    # link view
    lv = ll_view(c)
    if d != lv:
        print("DIVERGE", tag, "dict:", d, "ll:", lv); return False
    if d != model:
        print("MODEL-MISMATCH", tag, "cache:", d, "model:", model); return False
    # every read path
    for k in model:
        if c[k] != model[k]: print("GETITEM", tag, k); return False
        if c.get(k) != model[k]: print("GET", tag, k); return False
    if dict(c) != model or list(c.values()) != list(model.values()) \
       or list(c.items()) != list(model.items()) or list(c) != list(model) \
       or repr(c) is None:
        print("READS", tag, dict(c), model); return False
    if len(c) != len(model): print("LEN", tag); return False
    # flattened ll has same key set (incl. anchor sentinel at index)
    flat = c._get_flattened_ll()
    keys = [k for k,_ in flat[1:]]  # first is anchor
    if sorted(keys) != sorted(model): print("LLKEYS", tag, keys, model); return False
    if len(set(keys)) != len(keys): print("LLDUP", tag, keys); return False
    return True

