import sys
from collections import OrderedDict, UserDict, Counter, defaultdict

def load(path):
    for m in [k for k in sys.modules if k.startswith('boltons')]:
        del sys.modules[m]
    sys.path.insert(0, path)
    import boltons.cacheutils as cu
    sys.path.pop(0)
    return cu

def run(fn):
    try:
        r = fn()
        return repr(r) if isinstance(r, (bool, int)) else ("ret:"+type(r).__name__)
    except RecursionError:
        return "RECURSION"
    except Exception as e:
        return type(e).__name__

def build(cu):
    L={}
    # --- target fixed cases ---
    L['cache==dict']        = lambda: cu.LRU(values={'color':'blue'}) == {'color':'blue'}
    L['dict==cache']        = lambda: {'color':'blue'} == cu.LRU(values={'color':'blue'})
    L['cache!=dict']        = lambda: cu.LRU(values={'color':'blue'}) != {'color':'blue'}
    L['dict!=cache']        = lambda: {'color':'blue'} != cu.LRU(values={'color':'blue'})
    # --- other mapping types ---
    L['defaultdict==cache'] = lambda: cu.LRU(values={'a':1}) == defaultdict(int, a=1)
    L['cache==defaultdict'] = lambda: defaultdict(int, a=1) == cu.LRU(values={'a':1})
    L['Counter==cache']     = lambda: cu.LRU(values={'a':1}) == Counter(a=1)
    L['cache==Counter']     = lambda: Counter(a=1) == cu.LRU(values={'a':1})
    # --- non-dict types with same length ---
    L['cache==set']         = lambda: cu.LRU(values={'a':1}) == {'a'}
    L['cache==tuple']       = lambda: cu.LRU(values={'a':1}) == ('a',)
    L['cache==list_len1']   = lambda: cu.LRU(values={'a':1}) == ['a']
    L['list_len1==cache']   = lambda: ['a'] == cu.LRU(values={'a':1})
    L['cache==object']      = lambda: cu.LRU(values={'a':1}) == object()
    L['cache==str']         = lambda: cu.LRU(values={'a':1}) == "hi"
    # --- edge: exact dict is a subclass-of-dict but type()==dict? already covered
    # --- self-referential dict value ---
    L['nested_cache']       = lambda: (lambda c: (c.__setitem__('x', {'n':1}), c=={'x':{'n':1}})[1])(cu.LRU())
    # --- empty vs empty ---
    L['LRI=={}']            = lambda: cu.LRI() == {}
    L['{}==LRI']            = lambda: {} == cu.LRI()
    # --- copy() which returns dict ---
    L['cache.copy()==cache']= lambda: (lambda c: c.copy()==c)(cu.LRU(values={'a':1}))
    return L

for tag,path in [('PRISTINE','work/pristine/repo'),('FIXED','work/repo')]:
    cu=load(path); res={k:run(f()) for k,f in build(cu).items()}
    print("====",tag)
    for k,v in res.items(): print(f"   {k:<25} {v}")
