from pathlib import Path
p = Path("ranges/subset.js")
s = p.read_text()

# build both range strings up front
old = """  // the whole simple dom range, as a string, so that a version can be tested
  // against every one of its comparators at once (prerelease handling in
  // `satisfies` looks at the range as a whole, not at a single comparator).
  const domRange = dom.map(c => String(c)).join(' ')
"""
new = """  // a version can only be tested against a whole simple range, never against
  // one of its comparators in isolation: `satisfies` only allows a prerelease
  // when some comparator in the range carries the same version tuple, so
  // testing comparators one at a time loses the one granting that permission.
  const domRange = dom.map(c => String(c)).join(' ')
"""
assert s.count(old) == 1
s = s.replace(old, new)

old_eq = """  // will iterate one or zero times
  for (const eq of eqSet) {
    if (gt && !satisfies(eq, String(gt), options)) {
      return null
    }

    if (lt && !satisfies(eq, String(lt), options)) {
      return null
    }

    // test against the whole dom simple range, not one comparator at a time:
    // a prerelease is only allowed when some comparator in the range carries
    // the same tuple, and that comparator need not be the one being checked.
    if (!satisfies(String(eq), domRange, options)) {
      return false
    }

    return true
  }"""
new_eq = """  const subRange = sub.map(c => String(c)).join(' ')

  // will iterate one or zero times
  for (const eq of eqSet) {
    // the single = version has to survive the sub range's own bounds, or this
    // simple range is a null set
    if (!satisfies(String(eq), subRange, options)) {
      return null
    }

    if (!satisfies(String(eq), domRange, options)) {
      return false
    }

    return true
  }"""
assert s.count(old_eq) == 1
s = s.replace(old_eq, new_eq)

# subRange is only needed inside the eq branch, but building it before the
# early returns is harmless; keep it next to domRange for clarity instead
old_sr = """  const subRange = sub.map(c => String(c)).join(' ')

  // will iterate one or zero times"""
assert s.count(old_sr) == 1

# reflect the change in the algorithm comment at the top
old_doc = """//   - If GT, and EQ does not satisfy GT, return true (null set)
//   - If LT, and EQ does not satisfy LT, return true (null set)"""
new_doc = """//   - If EQ does not satisfy c, the whole simple range is a null set"""
assert s.count(old_doc) == 1
s = s.replace(old_doc, new_doc)

p.write_text(s)
print('patched')
