const pick = a => a[Math.floor(rnd() * a.length)]

const ops = ['', '=', '>', '>=', '<', '<=']
const vers = [
  '0.0.1', '1.0.0', '1.2.3', '1.5.0', '2.0.0', '3.1.4',
