    universe.add(`${a}.${b}.${c}-pre.0`)
    universe.add(`${a}.${b}.${c}-pre.1`)
    universe.add(`${a}.${b}.${c}-beta`)
    universe.add(`${a}.${b}.${c}-alpha.1`)
  }
}
