  const LETTERDASHNUMBER = '[a-zA-Z0-9-]'
  const reps = [['\\s', 1], ['\\d', MAX_LENGTH], [LETTERDASHNUMBER, MAX_SAFE_BUILD_LENGTH]]
  for (const [token, max] of reps) {
    value = value.split(`${token}*`).join(`${token}{0,${max}}`)
      .split(`${token}+`).join(`${token}{1,${max}}`)
  }
  return value
}
const oldFull = src[t.COERCEPLAIN] +
  `(?:${src[t.PRERELEASE]})?` +
  `(?:${src[t.BUILD]})?` +
  `(?:$|[^\\d])`
const oldFullSafe = makeSafe(oldFull)
const oldRe = new RegExp(oldFull)
const oldSafeRe = new RegExp(oldFullSafe)
const oldSafeRtlRe = new RegExp(oldFullSafe, 'g')
const newSafeRtlRe = safeRe[t.COERCERTLFULL]

// Old coerce logic, byte-for-byte copy of functions/coerce.js with regexes swapped
const coerceOld = (version, options) => {
  if (version instanceof SemVer) return version
  if (typeof version === 'number') version = String(version)
  if (typeof version !== 'string') return null
  options = options || {}
  let match = null
  if (!options.rtl) {
    match = version.match(options.includePrerelease ? oldSafeRe : safeRe[t.COERCE])
  } else {
    const coerceRtlRegex = options.includePrerelease ? oldSafeRtlRe : safeRe[t.COERCERTL]
    let next
    while ((next = coerceRtlRegex.exec(version)) &&
        (!match || match.index + match[0].length !== version.length)) {
