const oldFull = src[t.COERCEPLAIN] + `(?:${src[t.PRERELEASE]})?` + `(?:${src[t.BUILD]})?` + `(?:$|[^\\d])`
const oldSafeRe = new RegExp(makeSafe(oldFull))
const oldSafeRtlRe = new RegExp(makeSafe(oldFull), 'g')
const coerceOld = (version, options) => {
  if (version instanceof SemVer) return version
  if (typeof version === 'number') version = String(version)
  if (typeof version !== 'string') return null
  options = options || {}
  let match = null
  if (!options.rtl) {
    match = version.match(options.includePrerelease ? oldSafeRe : safeRe[t.COERCE])
  } else {
    const rx = options.includePrerelease ? oldSafeRtlRe : safeRe[t.COERCERTL]
    let next
    while ((next = rx.exec(version)) && (!match || match.index + match[0].length !== version.length)) {
      if (!match || next.index + next[0].length !== match.index + match[0].length) match = next
      rx.lastIndex = next.index + next[1].length + next[2].length
    }
    rx.lastIndex = -1
  }
  if (match === null) return null
  const pre = options.includePrerelease && match[5] ? `-${match[5]}` : ''
  const build = options.includePrerelease && match[6] ? `+${match[6]}` : ''
