// (a) inputs with NO segment of the form digits-then-letter => expect zero diffs
let seed = 4242
const rnd = () => { seed = (seed * 1103515245 + 12345) & 0x7fffffff; return seed / 0x7fffffff }
const pick = a => a[Math.floor(rnd() * a.length)]
const safeSegs = ['0','07','1','4821','rc','nightly','a7f3','x','0a','abc123','-','-x','0x']
const alpha = '0123456789.-+_abzxAZ '
let diffs = 0, checked = 0, sample = null
for (let i = 0; i < 50000; i++) {
  let s
  if (rnd() < 0.5) {
    s = pick(['','v','=']) + pick(['1','12','0','007']) + '.' + pick(['2','09','0']) + '.' + pick(['3','007','0']) +
