  const preres = s.split(/[+-]/).slice(1)
  const hasBugClass = preres.some(p => p.split('.').some(seg => /^\d+[A-Za-z]/.test(seg.split('+')[0])))
  if (hasBugClass) continue
  checked++
  for (const rtl of [false, true]) {
    const o = show(coerceOld(s, { includePrerelease: true, rtl }))
    const n = show(coerceNew(s, { includePrerelease: true, rtl }))
